// cockpit Panneau, QUOTAS unfolded: the 5 h and week curves (Julian, 19 Oct: « progression »): the readings of the
// current window (usage's samples.jsonl, lib/core/usage.mjs claudeSeries) and the engine's latest figure, with a
// dashed projection to the reset at the current rate; red when it passes 100 %, with « à ce rythme : 100 % vers
// HH:MM ». The current rate = the slope over the last `rate_min` minutes of readings (5 h: 60, week: 24 h), else over
// the whole window. Pure: no $, no I/O (node --test mods/cockpit/tests/viz.test.mjs).

const MIN = 60000
const H = 3600000

export const QUOTA_DEFAULTS = {
  five: { span_h: 5, rate_min: 60 },
  week: { span_h: 168, rate_min: 1440 },
  labels: { hit: 'à ce rythme : 100 % vers {at}', reach: 'à ce rythme : {pct} % au reset', days: ['dim', 'lun', 'mar', 'mer', 'jeu', 'ven', 'sam'] },
}

const p2 = (n) => String(n).padStart(2, '0')
/** « 14:20 », or « jeu 14:20 » when it is not within the next 20 h (local clock). */
export function atText(ms, now, days = QUOTA_DEFAULTS.labels.days) {
  const d = new Date(ms)
  const hm = `${p2(d.getHours())}:${p2(d.getMinutes())}`
  return ms - now > 20 * H ? `${days[d.getDay()]} ${hm}` : hm
}

/**
 * The projection of one window. readings: [{ ts, pct }] oldest first; o: { pct (the engine's figure now, wins over the
 * last reading), reset (ms; else the readings' own), now, span_h, rate_min }.
 * -> null without a reading, else { start, end, now, points, last, ratePerH, projPct (at the reset), hitAt (ms when
 *    100 % is reached before the reset, else null), over }.
 */
export function quotaProjection(readings, o = {}) {
  const now = Number(o.now) || Date.now()
  const given = (readings || []).filter((r) => r && Number.isFinite(r.reset)).pop()
  const reset = Number.isFinite(o.reset) ? o.reset : given ? given.reset : NaN
  const pts = (readings || []).filter((r) => r && Number.isFinite(r.ts) && Number.isFinite(r.pct) && r.ts <= now).map((r) => ({ ts: r.ts, pct: r.pct }))
  if (Number.isFinite(o.pct)) {
    if (pts.length && now - pts[pts.length - 1].ts < MIN) pts[pts.length - 1] = { ts: now, pct: o.pct }
    else pts.push({ ts: now, pct: o.pct })
  }
  if (!pts.length) return null
  const span = (Number(o.span_h) || 5) * H
  const end = Number.isFinite(reset) && reset > now ? reset : null
  const start = end ? end - span : pts[0].ts
  const inWin = pts.filter((p) => p.ts >= start)
  const points = inWin.length ? inWin : [pts[pts.length - 1]]
  const last = points[points.length - 1]
  const recent = points.filter((p) => p.ts >= last.ts - (Number(o.rate_min) || 60) * MIN)
  const base = recent.length >= 2 ? recent : points
  const first = base[0]
  const dt = last.ts - first.ts
  const ratePerH = dt > 0 ? Math.max(0, ((last.pct - first.pct) / dt) * H) : null
  let projPct = last.pct
  let hitAt = last.pct >= 100 ? last.ts : null
  if (end && ratePerH !== null) {
    projPct = last.pct + (ratePerH * (end - last.ts)) / H
    if (hitAt === null && ratePerH > 0 && projPct >= 100) hitAt = last.ts + ((100 - last.pct) / ratePerH) * H
  }
  return { start, end, now, points, last, ratePerH, projPct, hitAt, over: hitAt !== null }
}

/** The text under a curve: « à ce rythme : 100 % vers 14:20 » (red) or « à ce rythme : 64 % au reset », else ''. */
export function projectionText(p, labels = {}) {
  const L = { ...QUOTA_DEFAULTS.labels, ...labels }
  if (!p) return ''
  if (p.over) return L.hit.replace('{at}', atText(p.hitAt, p.now, L.days))
  if (p.end && p.ratePerH !== null) return L.reach.replace('{pct}', String(Math.round(p.projPct)))
  return ''
}

/**
 * Both windows. series: the cards scanner's quotaSeries ({ five, week }); usage: $.session.usage() ({ rateLimits:
 * [{ kind, percentUsed, resetsAt }] }); cfg: panel.viz.quota overrides. -> { five, week } (quotaProjection or null),
 * each with its `text`.
 */
export function quotaCurves({ series, usage, now }, cfg = {}) {
  const c = { ...QUOTA_DEFAULTS, ...(cfg || {}) }
  const limits = (usage && usage.rateLimits) || []
  const one = (id, kind) => {
    const r = limits.find((x) => x && x.kind === kind)
    const reset = r ? Date.parse(r.resetsAt || '') : NaN
    const p = quotaProjection((series && series[id]) || [], { now, pct: r && Number.isFinite(r.percentUsed) ? r.percentUsed : undefined, reset: Number.isFinite(reset) ? reset : undefined, ...c[id] })
    return p ? { ...p, text: projectionText(p, c.labels) } : null
  }
  return { five: one('five', 'five_hour'), week: one('week', 'seven_day') }
}

files.lib/viz_spark.mjs:
// cockpit Panneau, DÉBIT unfolded: a 24 h TPS sparkline per model next to each table's title (Julian, 19 Oct). One
// point per clock hour of the last `hours` (24): the weighted TPS of that model in that hour (all output tokens ÷ all
// time, every effort), null for an hour with no reply. From usage's debit.json hourly rows (`hour|model|effort`:
// [output, ms, streams, hist]), the same rows as lib/debit.mjs. Pure: no $, no I/O.
import { modelLabel, DEBIT_DEFAULTS } from './debit.mjs'

const HOUR = 3600000

/**
 * debit: usage's debit.json; now: ms; cfg: the cockpit config (panel.debit.aliases names the models as the cards do).
 * -> { [card label]: { values: [24 numbers | null], max, last } } for the Claude models (the cards' `label`).
 */
export function tpsHourly(debit, now, cfg = {}, hours = 24) {
  const aliases = { ...DEBIT_DEFAULTS.aliases, ...((cfg && cfg.panel && cfg.panel.debit && cfg.panel.debit.aliases) || {}) }
  const out = {}
  if (!debit || !debit.hourly) return out
  const first = Math.floor(now / HOUR) * HOUR - (hours - 1) * HOUR
  const acc = {}
  for (const [k, row] of Object.entries(debit.hourly)) {
    const [h, model] = k.split('|')
    const t = Number(h)
    if (!(t >= first) || t > now || !Array.isArray(row)) continue
    const i = Math.round((t - first) / HOUR)
    if (i < 0 || i >= hours) continue
    const label = modelLabel(model, aliases)
    const a = acc[label] || (acc[label] = Array.from({ length: hours }, () => [0, 0]))
    a[i][0] += Number(row[0]) || 0
    a[i][1] += Number(row[1]) || 0
  }
  for (const [label, a] of Object.entries(acc)) {
    const values = a.map(([o, ms]) => (ms > 0 ? o / (ms / 1000) : null))
    const known = values.filter((v) => v !== null)
    if (!known.length) continue
    out[label] = { values, max: Math.max(...known), last: [...values].reverse().find((v) => v !== null) }
  }
  return out
}

files.hooks/files.mjs:
// cockpit « Fichiers » - data-goblin's file tree (vendor/filetree, MIT, Kurt Buhler; see lib/filetree/LICENSE and
// NOTICE) embedded at the top of the Panneau. Two mods' panes in one column become tabs, so the only way to show the
// tree above the rest is to draw it here. The tree logic is filetree's own code, byte copies in lib/filetree/hooks
// (tree.ts: listing order, git status parsing, visible rows; icons.ts: git colours); this file only holds the state
// as plain data; register.mjs does the I/O, read-only: $.fs.list, `git status` / `git rev-parse` (--no-optional-locks,
// as filetree runs them). Pure: no $ here (a mod's validator follows $ only inside one file).
// Behaviour kept from filetree: a click on a folder opens or closes it (listed on demand), a click on a file selects it,
// and the next prompt carries the same context line filetree adds (« The user has this file selected in the file
// tree ... »), only while a file is selected by a click (panel.fichiers.attach_selection, on by default). Not here:
// search, preview, activity flashes, sizes, opening files (use filetree's own pane for those).
import { emptyTree, toNodes, replaceChildren, parseGit, posix, visibleRows, useDrives, inside, relative } from '../lib/filetree/hooks/tree.ts'
import { GIT_COLOR } from '../lib/filetree/hooks/icons.ts'

/** The tree's state, in memory (a reload starts from the cwd again). */
export function newFiles() {
  return { ...emptyTree(''), showHidden: false, limit: 0, busy: false, error: '', at: 0 }
}

/** A listing of $.fs.list (links already resolved by the caller) as filetree's nodes, sorted as filetree sorts them. */
export function nodesOf(dir, entries) {
  return toNodes(dir, entries)
}

/** Puts freshly listed folders ({ dir: nodes }) into the tree, as filetree does. */
export function applyListed(F, listed) {
  F.nodes = replaceChildren(F.nodes, listed)
}

/** `git rev-parse --show-prefix --show-toplevel` (null: no repo). */
export function applyTop(F, stdout) {
  const [p = '', tl = ''] = stdout === null ? [] : String(stdout).split(/\r?\n/)
  F.prefix = p.trim()
  F.top = tl.trim() || '-'
}

/** `git status --porcelain=v1 -b -z` -> the git letters and the branch. */
export function applyGit(F, stdout) {
  const g = parseGit(String(stdout || ''), F.root, F.prefix)
  F.git = g.git
  F.branch = g.branch
}

/** Points the tree at `root` (posix, no trailing slash); the caller lists it. */
export function resetTo(F, root, windows, showHidden) {
  useDrives(Boolean(windows))
  const r = posix(String(root || '')).replace(/\/+$/, '')
  Object.assign(F, { ...emptyTree(r), showHidden: Boolean(showHidden), limit: F.limit || 0, busy: false, error: '' })
  return r
}

/** The folders to list again on a refresh: the root and the open ones. */
export function openDirs(F) {
  return F.root ? [F.root, ...F.expanded.filter((d) => inside(F.root, d))] : []
}

/** A click on a row: a folder opens or closes, a file is selected (a second click clears it). Returns the folder the
 *  caller must list before the folder opens (null otherwise); then the caller calls openDir. */
export function filesPress(F, id) {
  const n = F.nodes.find((x) => x.id === id)
  if (!n) return null
  F.cursor = n.id
  if (n.kind === 'dir') {
    if (F.expanded.includes(n.id)) { F.expanded = F.expanded.filter((d) => d !== n.id); return null }
    return n.id
  }
  F.selected = F.selected === n.id ? '' : n.id
  return null
}

export function openDir(F, id) {
  if (!F.expanded.includes(id)) F.expanded = [...F.expanded, id]
}

export function filesClear(F) {
  F.selected = ''
}

/** The rows the panel draws: [{ id, depth, label, kind, open, git, color, selected }], at most `max`. */
export function filesRows(F, max) {
  if (!F.root) return { rows: [], more: 0 }
  const all = visibleRows(F)
  const rows = all.slice(0, Math.max(1, max)).map((r) => ({
    id: r.node.id, depth: r.depth, kind: r.node.kind, open: r.open,
    label: `${'  '.repeat(r.depth)}${r.node.kind === 'dir' ? (r.open ? '▾' : '▸') : '·'} ${r.node.name}`,
    git: F.git[r.node.id] || '', color: GIT_COLOR[F.git[r.node.id] || ''] || undefined, selected: F.selected === r.node.id,
  }))
  return { rows, more: Math.max(0, all.length - rows.length) }
}

/** The header: folder name and branch. */
export function filesHead(F) {
  const name = F.root.split('/').pop() || F.root
  const b = F.branch && F.branch.head ? ` · ${F.branch.head}${F.branch.ahead ? ` ↑${F.branch.ahead}` : ''}${F.branch.behind ? ` ↓${F.branch.behind}` : ''}` : ''
  return `${name}${b}`
}

export function filesShort(F, path) {
  return F.root && inside(F.root, path) ? relative(F.root, path) || path : path
}

/** The context line filetree adds to a prompt while a file is selected (same words, so Claude reads it the same way). */
export function filesContext(F) {
  return F.selected ? `The user has this file selected in the file tree; "this" or "it" in the prompt likely refers to it: ${F.selected}` : ''
}

