    if (!single) out.push(h.T(clip(fill(L.graphe_group, { name: (g.starred ? '★ ' : '') + g.name, n: g.count }), width), { dim: true, wrap: 'truncate-end', key: 'pgg-' + g.name }))
    for (const r of g.lines) {
