        h.row([pad ? h.T(nb(pad)) : null, h.T(r.dot, { tone: r.tone === 'dim' ? undefined : r.tone, dim: r.tone === 'dim' || !r.tone }), h.btn(`${clip(r.title, room)}${tail} ${unfolded ? '⌄' : '›'}`, () => (act.nodeToggle || NOOP)(convKey(r.key), unfolded), false, 'pgl-' + r.key),
